The greedy max function $g_\varepsilon(x, y)$ is the maximum value of $f(x, \cdot)$ attainable by {\em any} $\varepsilon$-greedy path in the set  $S_{\varepsilon, x, y}$:


\begin{equation} g_\varepsilon(x,y):= \sup \{f(x,z) : z\in  S_{\varepsilon, x, y}\}.
\end{equation}

As a simple example  (Figure \ref{fig:discontinuity}), consider the function
\begin{equation*}
    f(x,y) = \cos(x+y)\sin(2x+2y) - e^{-x^2}.
    \end{equation*}

 For any $0< \varepsilon < 0.1$, the greedy max function $g_{\varepsilon}(x,y)$ is discontinuous at the (parallel) lines $x+y = -2.52$ and $x+y = -0.62$, with $g_{\varepsilon} (x,y) = -e^{-x^2}$ in the region enclosed between the two lines and $g_{\varepsilon} (x,y) = -e^{-x^2}+0.77$ on each side of that region. 

  Such examples are easy to come by and extend to higher dimensions.

\|\nabla_y f(x^\star, y^\star)\| \leq \varepsilon
 \quad \textrm{and} \quad

 \lambda_{\mathrm{max}}( \nabla^2_{y} f(x^\star, y^\star)) \leq \sqrt{L \varepsilon}, \textrm{ and }

In addition to oracles for $f$, $\nabla_y f$ and $\nabla^2_y f$, our algorithm also takes as input an initial point $(x_0, y_0)$ in $\mathbb{R}^d \times \mathbb{R}^d$, and parameters $\varepsilon, \sigma >0$  (recall we have set $\sigma = \frac{1}{\sqrt{d}}$ in this section). \footnote{In the full description of the algorithm we set  $(x_0, y_0) = (0, 0)$ for simplicity.}

\begin{enumerate}
\item  Starting at the initial point $(x_0, y_0)$, our algorithm first uses the second-order optimization method described in Section \ref{sec_local_approx} (Algorithm \ref{alg:InnerMaxLoop}) to find a point $y_1$ which is an  $(\varepsilon, \sqrt{\varepsilon})$-approximate local maximum for $f(x_0, \cdot)$.

\item Next, starting from iteration $i=1$, and setting $x_1 \leftarrow x_0$,  our algorithm uses noisy SGD (Equation \eqref{eq_noisySGD})\footnote{In the full algorithm we combine noisy SGD with a a random hill-climbing method (Lines \ref{RebootStart_hill}-\ref{RebootEnd_hill}  of Algorithm \ref{alg:LocalMin-max}).}
 to search for a point $x_{i+1}$ for which,
\begin{equs} h_\varepsilon(x_{i+1}, y_{i}) \leq h_\varepsilon(x_i, y_{i})  - \gamma_1,
\end{equs}
   where $\gamma_1 = \mathrm{poly}(\frac{1}{d},  \varepsilon)$ (Lines \ref{RebootStart}-\ref{RebootEnd} of Algorithm \ref{alg:LocalMin-max}).

   When running noisy SGD, roughly speaking, our algorithm uses the stochastic gradient $\Gamma$ (the same stochastic gradient as in Equation \eqref{eq_gradient_free_SG}),
   \begin{equation}
 \Gamma(w) = \frac{\zeta}{\sigma} \min \left(h_\varepsilon(w + \sigma \zeta, y_{i}), h_\varepsilon(x_i,y_{i})\right),
\end{equation}


where $\zeta \sim N(0,I_d)$ and $h_\varepsilon$ is computed using the second-order optimization method of Section \ref{sec_local_approx} (Algorithm \ref{alg:InnerMaxLoop}).


  \item

If our algorithm is able to find an update $x_{i+1}$ which satisfies Inequality \eqref{eq_decrease}, it uses Algorithm \ref{alg:InnerMaxLoop} to compute a point $y_{i+1}$, which is an $(\varepsilon, \sqrt{\varepsilon})$-approximate local maximum for $f(x_{i+1},\cdot)$,

 sets $i\leftarrow i+1$,  and goes back to Step 2.

  Otherwise, if it cannot find such an update, it concludes that $x_i$ is an $(\varepsilon, \sigma)$-approximate local minimum for $h_\varepsilon(\cdot ,y_{i}$), and, hence, that $(x_i,y_{i})$ is a  $(\varepsilon, \sigma)$-greedy adversarial equilibrium.

\end{enumerate}

Next, starting from iteration $i=1$, and setting $x_1 \leftarrow x_0$,  our algorithm uses noisy SGD (Equation \eqref{eq_noisySGD})\footnote{In the full algorithm we combine noisy SGD with a a random hill-climbing method (Lines \ref{RebootStart_hill}-\ref{RebootEnd_hill}  of Algorithm \ref{alg:LocalMin-max}).}
 to search for a point $x_{i+1}$ for which,
\begin{equs} h_\varepsilon(x_{i+1}, y_{i}) \leq h_\varepsilon(x_i, y_{i})  - \gamma_1,
\end{equs}
   where $\gamma_1 = \mathrm{poly}(\frac{1}{d},  \varepsilon)$ (Lines \ref{RebootStart}-\ref{RebootEnd} of Algorithm \ref{alg:LocalMin-max}).

   When running noisy SGD, roughly speaking, our algorithm uses the stochastic gradient $\Gamma$ (the same stochastic gradient as in Equation \eqref{eq_gradient_free_SG}),
   \begin{equation}
 \Gamma(w) = \frac{\zeta}{\sigma} \min \left(h_\varepsilon(w + \sigma \zeta, y_{i}), h_\varepsilon(x_i,y_{i})\right),
\end{equation}


where $\zeta \sim N(0,I_d)$ and $h_\varepsilon$ is computed using the second-order optimization method of Section \ref{sec_local_approx} (Algorithm \ref{alg:InnerMaxLoop}).

